const exec = $json.execution || {};
const wf = $json.workflow || {};
const err = exec.error || {};
const nodeName = err.node ? err.node.name : (exec.lastNodeExecuted || "Unknown node");
const errorMsg = err.message || "Unknown error";
const executionId = exec.id || "-";
const executionUrl = exec.url || "-";
const workflowName = wf.name || "Meeting Notes Pipeline";
const now = new Date();
const timestamp = now.toLocaleString("id-ID", { timeZone: "Asia/Jakarta", hour12: false });
const message = ["*Error: " + workflowName + " Gagal*","","*Node Gagal:* " + nodeName,"*Error:* " + errorMsg,"*Waktu:* " + timestamp,"*Execution ID:* #" + executionId,"Lihat execution: " + executionUrl].join("
");
return [{ json: { message, nodeName, errorMsg, executionId, executionUrl, workflowName } }];
